import { Object3D, Mesh, PlaneGeometry, BoxGeometry, Group, Color, Vector3 } from 'three/webgpu';
import {
    MeshBasicNodeMaterial,
    positionWorld,
    mix,
    add,
    mul,
    vec3,
    float
} from 'three/tsl';
import { gsap } from 'gsap';
import * as Primitives from '@/primitives';
import * as Text from '@/text';

export default function createNode(config, ctx) {
    const root = new Object3D();
    root.position.set(0, 0, 0);
    root.rotation.set(0, 0, 0);
    root.scale.set(1, 1, 1);
    root.userData.handlers = {};

    // -------------------------------------------------------------------------
    // Geometry & Materials
    // -------------------------------------------------------------------------
    const WIDTH = 6.8;
    const HEIGHT = 2.0;
    const HAIRLINE_THICK = 0.006;
    const BASE_COLOR_TOP = new Color('#121218');
    const BASE_COLOR_BOTTOM = new Color('#0b0b10');
    const HAIRLINE_COLOR = new Color('#23232b');
    const INK_COLOR = new Color('#16161d');
    const ACCENT_COLOR = new Color('#ff2a38');

    // Gradient node for background
    const gradientNode = mix(
        vec3(float(BASE_COLOR_TOP.r), float(BASE_COLOR_TOP.g), float(BASE_COLOR_TOP.b)),
        vec3(float(BASE_COLOR_BOTTOM.r), float(BASE_COLOR_BOTTOM.g), float(BASE_COLOR_BOTTOM.b)),
        add(mul(positionWorld.y, 0.5), 0.5)
    );

    const bgMaterial = new MeshBasicNodeMaterial({
        color: gradientNode,
        transparent: true,
        opacity: 0
    });

    const bgPlane = new Mesh(new PlaneGeometry(WIDTH, HEIGHT), bgMaterial);
    bgPlane.position.set(0, 0, 0);
    root.add(bgPlane);

    // Top hairline
    const topHairlineMat = new MeshBasicNodeMaterial({
        color: HAIRLINE_COLOR,
        transparent: true,
        opacity: 0
    });
    const topHairline = new Mesh(new PlaneGeometry(WIDTH, HAIRLINE_THICK), topHairlineMat);
    topHairline.position.set(0, HEIGHT / 2 - HAIRLINE_THICK / 2, 0.001);
    root.add(topHairline);

    // =======================================================================
    // Helper to create MSDF text meshes
    // =======================================================================
    const textMeshes = [];
    const materialList = [bgMaterial, topHairlineMat];

    function addText(str, style, pos, extra = {}) {
        const mesh = Text.createTextMesh({
            text: str,
            fontFamily: style.family,
            fontWeight: style.fontWeight,
            fontSize: style.fontSize * 0.01, // convert px → scene units (approx)
            letterSpacing: style.letterSpacing,
            lineHeight: style.lineHeight,
            color: INK_COLOR,
            atlas: ctx.fontAtlas,
            ...extra
        });
        mesh.position.copy(pos);
        root.add(mesh);
        textMeshes.push(mesh);
        materialList.push(mesh.material);
        return mesh;
    }

    // -------------------------------------------------------------------------
    // Wordmark block (left side)
    // -------------------------------------------------------------------------
    const leftEdge = -WIDTH / 2;
    const wordBlockXCenter = leftEdge + 1.0; // block width 2.0, center offset 1.0
    const wordmarkYTop = HEIGHT / 2 - 0.3; // some margin from top

    // Wordmark
    const wordmarkStyle = {
        family: 'Lora',
        fontSize: 34,
        fontWeight: 600,
        letterSpacing: 0.02,
        lineHeight: 1
    };
    const wordmarkPos = new Vector3(wordBlockXCenter, wordmarkYTop, 0.01);
    addText('NOVA ATELIER', wordmarkStyle, wordmarkPos);

    // Accent bar beneath wordmark
    const accentBarWidth = 0.3;
    const accentBarHeight = 0.02;
    const accentBarMat = new MeshBasicNodeMaterial({
        color: ACCENT_COLOR,
        emissive: ACCENT_COLOR,
        emissiveIntensity: 1.4,
        transparent: true,
        opacity: 0
    });
    const accentBar = new Mesh(new BoxGeometry(accentBarWidth, accentBarHeight, 0.001), accentBarMat);
    // Position: same X, Y a bit below wordmark baseline
    const accentBarPosY = wordmarkYTop - 0.12; // arbitrary offset for visual balance
    accentBar.position.set(wordBlockXCenter, accentBarPosY, 0.01);
    root.add(accentBar);
    materialList.push(accentBarMat);

    // -------------------------------------------------------------------------
    // Link Columns (right side)
    // -------------------------------------------------------------------------
    const gutter = 0.375;
    const columnWidth = 1.2;
    const columnStartX = leftEdge + 2.0 + gutter + columnWidth / 2; // first column center

    const columns = [
        {
            header: 'ATELIER',
            links: ['Features', 'Collection', 'Pricing']
        },
        {
            header: 'COMPANY',
            links: ['Journal', 'Visit the Atelier', 'Contact']
        },
        {
            header: 'LEGAL',
            links: ['Privacy', 'Terms', 'Warranty']
        }
    ];

    const headerStyle = {
        family: 'JetBrains Mono',
        fontSize: 9,
        fontWeight: 700,
        letterSpacing: 0.12,
        lineHeight: 1.2
    };
    const linkStyle = {
        family: 'JetBrains Mono',
        fontSize: 13,
        fontWeight: 400,
        letterSpacing: 0,
        lineHeight: 1.8
    };

    const columnTopY = HEIGHT / 2 - 0.5; // some top margin inside band
    const lineHeight = linkStyle.lineHeight * (linkStyle.fontSize * 0.01);
    const headerOffsetY = 0;
    const linksOffsetY = -0.15; // space below header

    columns.forEach((col, idx) => {
        const colCenterX = columnStartX + idx * (columnWidth + gutter);
        // Header
        const headerPos = new Vector3(colCenterX, columnTopY + headerOffsetY, 0.01);
        addText(col.header, headerStyle, headerPos);
        // Links
        col.links.forEach((linkText, li) => {
            const linkPos = new Vector3(
                colCenterX,
                columnTopY + linksOffsetY - li * lineHeight,
                0.01
            );
            addText(linkText, linkStyle, linkPos);
        });
    });

    // -------------------------------------------------------------------------
    // Legal line (bottom)
    // -------------------------------------------------------------------------
    const legalStyle = {
        family: 'JetBrains Mono',
        fontSize: 9,
        fontWeight: 400,
        letterSpacing: 0.04,
        lineHeight: 1.4
    };
    const legalY = -HEIGHT / 2 + 0.375;
    const legalPos = new Vector3(0, legalY, 0.01);
    addText(
        '(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.',
        legalStyle,
        legalPos
    );

    // Bottom hairline (separating legal line)
    const bottomHairlineMat = new MeshBasicNodeMaterial({
        color: HAIRLINE_COLOR,
        transparent: true,
        opacity: 0
    });
    const bottomHairline = new Mesh(new PlaneGeometry(WIDTH, HAIRLINE_THICK), bottomHairlineMat);
    // Position: 0.25 clearance below legal line
    const bottomHairlineY = legalY - 0.25 - HAIRLINE_THICK / 2;
    bottomHairline.position.set(0, bottomHairlineY, 0.001);
    root.add(bottomHairline);
    materialList.push(bottomHairlineMat);

    // -------------------------------------------------------------------------
    // Animation (fade‑up whole band)
    // -------------------------------------------------------------------------
    // Start slightly above and invisible
    root.position.y += 0.2;
    materialList.forEach(mat => {
        mat.transparent = true;
        mat.opacity = 0;
    });

    const timeline = gsap.timeline();
    timeline.to(
        root.position,
        {
            y: root.position.y - 0.2,
            duration: 0.5,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        },
        0
    );
    timeline.to(
        materialList,
        {
            opacity: 1,
            duration: 0.5,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        },
        0
    );

    // -------------------------------------------------------------------------
    // Cleanup
    // -------------------------------------------------------------------------
    root.userData.cleanup = () => {
        timeline.kill();
        materialList.forEach(m => m.dispose && m.dispose());
        bgPlane.geometry.dispose();
        topHairline.geometry.dispose();
        bottomHairline.geometry.dispose();
        accentBar.geometry.dispose();
        textMeshes.forEach(m => {
            m.geometry && m.geometry.dispose();
            m.material && m.material.dispose && m.material.dispose();
        });
    };

    // -------------------------------------------------------------------------
    // Export
    // -------------------------------------------------------------------------
    return root;
}
